function personAvatar(id,cls='tiny-avatar'){let p=getPerson(id);return p?`<span class="${cls}" style="background:${p.color}" title="${esc(p.name)}">${esc(initials(p.name))}</span>`:`<span class="${cls} none" title="Не призначено">?</span>`}
const statusLabels={planned:'Planned',progress:'In Progress',hold:'On Hold',done:'Done'};
let workspace=structuredClone(initialWorkspace);
