function newProjectData(){
 const start=monday(today());return {version:4,features:[],tasks:[],people:[],roles:[],meetings:[],leave:[],
 iterations:[{id:uid('i'),name:'Iteration 1',start,end:addDays(start,13),overrides:{}},{id:uid('i'),name:'Iteration 2',start:addDays(start,14),end:addDays(start,27),overrides:{}}],
 milestones:[],holidays:[],settings:{observeHolidays:false,defaultCapacity:{feature:100,bugs:0,ongoing:0,ops:0},workHours:8,autoShiftDependencies:false,dependencyGapDays:0,dependencyGapUnit:'calendar',dependencyShiftPolicy:'push',showDependencyWarnings:true},createdAt:today()};
}
function guessPlatform(role){
 let r=role.toLowerCase().trim();
 if(/(back.?end|server.side)/.test(r))return 'Backend';
 if(/(front.?end|ui developer|web developer)/.test(r))return 'Frontend';
 if(/(android)/.test(r))return 'Android';
 if(/(ios|swift)/.test(r))return 'iOS';
 if(/(qa|quality assurance|test engineer|tester|sdet)/.test(r))return 'QA';
 if(/(devops|sre|infrastructure)/.test(r))return 'DevOps';
 if(/(design|ux|ui artist)/.test(r))return 'Design';
 if(/(data|ml|machine learning|ai engineer)/.test(r))return 'Data / ML';
 if(/(product manag|product owner)/.test(r))return 'Product';
 return role.trim(); // new free-text roles also become usable workstreams
}
function migrateTeam(){
 if(!Array.isArray(data.roles)){
  const roles=new Map();
  data.people.forEach(p=>{const name=p.role||p.platform||'Team member',platform=p.platform||name,key=name.toLowerCase()+'|'+platform.toLowerCase();if(!roles.has(key))roles.set(key,{id:uid('r'),name,platform});p.roleId=roles.get(key).id});
  data.roles=[...roles.values()];
 }
 data.people.forEach(p=>{
  if(!p.roleId){let r=data.roles.find(r=>r.name===p.role&&r.platform===p.platform)||data.roles.find(r=>r.platform===p.platform);if(r)p.roleId=r.id}
  let r=data.roles.find(r=>r.id===p.roleId);if(r){p.role=r.name;p.platform=r.platform}
  if(p.firstName===undefined){const parts=String(p.name||'').trim().split(/\s+/);p.firstName=parts.shift()||'';p.lastName=parts.join(' ')}
  if(!p.capacity)p.capacity=copy(data.settings.defaultCapacity);
 });
}
migrateTeam(); // previous snapshots continue working, including their tasks and capacity
