function persist(){
 workspace.preferences={sidebarHidden:view.sidebarHidden,scale:view.scale,page:view.page};
 if(currentProject()){currentProject().data=data;currentProject().onboardingStep=view.setupStep;}
 callbacks.onChange(structuredClone(workspace));
}
function switchProject(id){
 const project=workspace.projects.find(p=>p.id===id);if(!project)return;
 persist();workspace.activeId=id;data=project.data;data.meetings||=[];migrateTeam();initializeDependencySettings(data);
 view.page='timeline';view.iteration=data.iterations[0]?.id;view.drawer=null;view.modal=null;view.setupStep=project.onboardingStep||0;view.rangeStart=alignScaleStart(today(),view.scale);view.scaleFocusDate=today();view.scrollToStart=true;view.showOnlyRisks=false;view.filterPerson='';view.filterPlatform='';
 persist();render();notify('Switched to '+project.name);
}
// Reuse setup from a different project without cloning its roadmap, work items, leave or milestones.
const normalized=s=>String(s||'').trim().toLocaleLowerCase();
const personKey=p=>normalized(p.name||[p.firstName,p.lastName].filter(Boolean).join(' '));
function sourceProjectOptions(){
 return workspace.projects.filter(p=>p.id!==workspace.activeId).map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${p.data.people.length} people, ${(p.data.meetings||[]).length} meetings</option>`).join('');
}
function teamIdMap(source){
 const result=new Map();
 (source.data.people||[]).forEach(person=>{const match=data.people.find(p=>personKey(p)===personKey(person));if(match)result.set(person.id,match.id)});
 return result;
}
function copyTeamSetup(source){
 const roles=source.data.roles||[],roleMap=new Map();let membersAdded=0,rolesAdded=0;
 roles.forEach(r=>{
  let dest=data.roles.find(x=>normalized(x.name)===normalized(r.name)&&normalized(x.platform)===normalized(r.platform));
  if(!dest){dest={...copy(r),id:uid('r')};data.roles.push(dest);rolesAdded++}
  roleMap.set(r.id,dest);
 });
 (source.data.people||[]).forEach(person=>{
  if(data.people.some(p=>personKey(p)===personKey(person)))return;
  let role=roleMap.get(person.roleId)||data.roles.find(r=>normalized(r.name)===normalized(person.role)&&normalized(r.platform)===normalized(person.platform));
  if(!role){role={id:uid('r'),name:person.role||person.platform||'Team member',platform:person.platform||guessPlatform(person.role||'Team member')};data.roles.push(role);rolesAdded++}
  const first=person.firstName??String(person.name||'').trim().split(/\s+/)[0]??'';
  const last=person.lastName??String(person.name||'').trim().split(/\s+/).slice(1).join(' ');
  data.people.push({...copy(person),id:uid('u'),name:person.name||[first,last].filter(Boolean).join(' '),firstName:first,lastName:last,roleId:role.id,role:role.name,platform:role.platform,capacity:copy(person.capacity||source.data.settings?.defaultCapacity||data.settings.defaultCapacity)});
  membersAdded++;
 });
 return {membersAdded,rolesAdded};
}
function copyMeetingSetup(source){
 let meetingsAdded=0,needsReview=0;const ids=teamIdMap(source);
 (source.data.meetings||[]).forEach(mt=>{
  if(data.meetings.some(m=>m.copiedFromProjectId===source.id&&m.copiedFromMeetingId===mt.id))return;
  // This fallback also avoids duplicates when the same event was created manually.
  if(data.meetings.some(m=>normalized(m.title)===normalized(mt.title)&&m.recurrence===mt.recurrence&&m.startTime===mt.startTime&&m.startDate===mt.startDate))return;
  let people=(mt.attendees||[]),attendees=[...new Set(people.map(pid=>ids.get(pid)).filter(Boolean))];
  const unmatched=!mt.allTeam&&attendees.length!==people.length;
  data.meetings.push({...copy(mt),id:uid('mt'),attendees,enabled:unmatched?false:mt.enabled!==false,requiresAttendeeReview:unmatched,copiedFromProjectId:source.id,copiedFromMeetingId:mt.id});
  meetingsAdded++;if(unmatched)needsReview++;
 });
 return {meetingsAdded,needsReview};
}
function importSetup(sourceId,includeTeam,includeMeetings){
 const source=workspace.projects.find(p=>p.id===sourceId&&p.id!==workspace.activeId);
 if(!source)return null;
 const result={membersAdded:0,rolesAdded:0,meetingsAdded:0,needsReview:0};
 if(includeTeam)Object.assign(result,copyTeamSetup(source));
 if(includeMeetings)Object.assign(result,copyMeetingSetup(source));
 return result;
}
function importSummary(result){
 if(!result)return 'Choose a source project';
 let details=[];
 if(result.membersAdded)details.push(`${result.membersAdded} team member(s)`);
 if(result.rolesAdded)details.push(`${result.rolesAdded} role(s)`);
 if(result.meetingsAdded)details.push(`${result.meetingsAdded} meeting(s)`);
 if(!details.length)details.push('Nothing new to copy · duplicates skipped');
 if(result.needsReview)details.push(`${result.needsReview} paused meeting(s) need attendee review`);
 return 'Copied: '+details.join(' · ');
}
function createProject(name,sourceId='',includeTeam=false,includeMeetings=false){
 const p={id:uid('proj'),name,data:newProjectData()};workspace.projects.push(p);workspace.activeId=p.id;data=p.data;
 const copied=sourceId?importSetup(sourceId,includeTeam,includeMeetings):null;
 view.page='timeline';view.iteration=data.iterations[0].id;view.drawer=null;view.modal=null;view.setupStep=1;view.rangeStart=monday(today());view.showOnlyRisks=false;
 persist();render();if(copied)notify(importSummary(copied));
}

function notify(msg){let root=$('#toast-root');if(!root)return;root.innerHTML=sanitizeMarkup(`<div class="toast">${icon('check',16)} ${esc(msg)}</div>`);clearTimeout(notify.t);notify.t=setTimeout(()=>root.innerHTML='',2900)}
let scheduling=createScheduler(data);
const isHoliday=(...args)=>scheduling.isHoliday(...args);
const nonwork=(...args)=>scheduling.nonwork(...args);
const nextWork=(...args)=>scheduling.nextWork(...args);
const meetingOccurs=(...args)=>scheduling.meetingOccurs(...args);
const meetingMinutes=(...args)=>scheduling.meetingMinutes(...args);
const meetingHoursInIteration=(...args)=>scheduling.meetingHoursInIteration(...args);
const featureCapacity=(...args)=>scheduling.featureCapacity(...args);
function meetingPeopleLabel(m){
 return m.allTeam?'Entire team':(m.attendees||[]).map(id=>getPerson(id)?.name).filter(Boolean).join(', ')||'No attendees';
}
function calcSchedule(){scheduling=createScheduler(data);return scheduling.calculate();}
let computed=calcSchedule();
const timeBreakdowns=new Map();
function taskBreakdown(t){if(!timeBreakdowns.has(t.id))timeBreakdowns.set(t.id,taskTimeBreakdown(t,computed.schedule[t.id],data,scheduling));return timeBreakdowns.get(t.id)}
function featureBreakdown(f,info){return info.end===null?null:featureTimeBreakdown(info.start,info.end,data.tasks.filter(t=>t.featureId===f.id).map(taskBreakdown),info.endFraction??1)}
function capacityBand(breakdown){return breakdown?`<i class="capacity-band" style="background:${capacityGradient(breakdown)}" aria-hidden="true"></i>`:''}
function capacityLegend(){return `<div class="capacity-legend" aria-label="Timeline colors">${timeCategories.map(([key,label,color])=>`<span><i style="background:${color}"></i>${label}</span>`).join('')}<button class="timeline-help" data-action="help" aria-label="Roadmap help" title="Scroll horizontally for earlier or later dates. Drag a row grip to reorder; end connectors link dependencies. Planning uses 0.5-day steps.">${icon('info',13)}</button><button class="dependency-mode" data-action="open-settings" aria-label="Dependency settings">Dependencies: ${data.settings.autoShiftDependencies?'auto-shift on':'manual placement'} ${icon('settings',12)}</button></div>`}
function breakdownText(b){return b?`Total capacity shares · ${b.days} calendar days · ${timeCategories.filter(([key])=>b.totals[key]>.00001).map(([key,label])=>label+': '+String(Math.round(b.totals[key]*100)/100)+'d').join(' · ')}${b.missing?' · '+b.missing+'d does not fit the selected dates':''}`:''}
function capacityDetails(t){const b=taskBreakdown(t);if(!b)return '';return `<div class="drawer-section"><div class="section-head">${t.effort}d effort · ${b.days} calendar days</div>${b.missing?`<div class="notice warn" role="status">${b.missing}d of effort does not fit these dates at the current capacity.</div>`:''}<p class="panel-sub">The bar shows total development, recurring meetings, weekends, holidays and absences across the selected dates. Planning uses 0.5-day steps; daily meeting time is rounded up once. The stored estimate and exact meeting minutes stay unchanged.</p>${timeCategories.filter(([key])=>b.totals[key]>.00001).map(([key,label,color])=>`<div class="metric-row"><span><i class="time-swatch" style="background:${color}"></i>${label}</span><strong>${Math.round(b.totals[key]*100)/100}d</strong></div>`).join('')}</div>`}
function validPlanDate(value){return /^\d{4}-\d{2}-\d{2}$/.test(value)&&value>='2000-01-01'&&value<='2200-12-31'&&Number.isFinite(asDay(value))}
function updateScheduleDates(item,info,kind,target){
 const key=target.id,value=target.value,start=info.start===null?item.start:fromDay(info.start),end=info.end===null?null:fromDay(info.end);
 if(key.endsWith('DateMode')){change(()=>{if(value==='automatic')delete item.manualEnd;else{item.start=start;item.manualEnd=end||start;}},'Date mode updated');return;}
 if(key.endsWith('End')&&!value){change(()=>delete item.manualEnd,'Automatic forecast restored');return;}
 if(!validPlanDate(value)){notify('Choose a valid date between 2000 and 2200');render();return;}
 if(key.endsWith('End')){
  if(value<start||asDay(value)-asDay(start)>=3650){notify('End must follow start within a 10-year window');render();return;}
  change(()=>{item.start=start;if(item.status==='done')item.completedDate=value;else item.manualEnd=value;},'End date updated');return;
 }
 if(item.status==='done'&&item.completedDate&&value>item.completedDate){notify('Start cannot follow the completion date');render();return;}
 const delta=asDay(value)-asDay(start),affected=kind==='feature'?data.tasks.filter(t=>t.featureId===item.id):[];
 const shifted=[...(item.manualEnd?[addDays(end||item.manualEnd,delta)]:[]),...affected.flatMap(t=>[addDays(t.start,delta),...(t.manualEnd?[addDays(t.manualEnd,delta)]:[])])];
 if(shifted.some(date=>!validPlanDate(date))){notify('Shifted dates must remain between 2000 and 2200');render();return;}
 change(()=>{item.start=value;if(item.manualEnd)item.manualEnd=addDays(end||item.manualEnd,delta);for(const task of affected){task.start=addDays(task.start,delta);if(task.manualEnd)task.manualEnd=addDays(task.manualEnd,delta);}},'Start date updated');
}
