function isFiltered(){return Boolean(view.filterPerson||view.filterPlatform)}
function matchingTasks(featureId){return data.tasks.filter(t=>t.featureId===featureId&&(!view.filterPerson||t.assignee===view.filterPerson)&&(!view.filterPlatform||t.platform===view.filterPlatform))}
function grouping(start,count,kind){let segments=[],last=null;for(let i=0;i<count;i++){let stamp=start+i,dt=new Date(stamp*DAY),year=dt.getUTCFullYear(),mon=dt.getUTCMonth(),key='',label='';
 if(kind==='decade'){let decade=Math.floor(year/10)*10;key=''+decade;label=decade+'–'+(decade+9)}
 else if(kind==='year'){key=''+year;label=''+year}
 else if(kind==='month'){key=year+'-'+mon;label=dt.toLocaleDateString('en-US',{month:'short',year:'numeric',timeZone:'UTC'})}
 else if(kind==='quarter'){let q=Math.floor(mon/3)+1;key=year+'-Q'+q;label='Q'+q+' '+year}
 else if(kind==='week'){let monDay=stamp-((dow(stamp)+6)%7);key=''+monDay;label='Wk '+dmy(fromDay(monDay))}
 else {key=''+stamp;label=''+dt.getUTCDate()}
 if(last!==key){segments.push({date:fromDay(stamp),label,count:0});last=key}segments[segments.length-1].count++}
 return segments;
}
function timeBand(groups,kind){return `<div class="time-band ${kind}">${groups.map(g=>`<div class="time-segment" style="width:${g.count*view.zoom}px" data-date="${g.date}" title="${fullD(g.date)} · Double-click to add milestone">${esc(g.label)}</div>`).join('')}</div>`}
function headings(){let start=asDay(view.rangeStart),days=view.days,scale=view.scale,cell=view.zoom;
 let header='';
 if(scale==='day'){const month=grouping(start,days,'month'),week=grouping(start,days,'week');header=timeBand(month,'upper')+timeBand(week,'middle')+`<div class="day-head">${Array.from({length:days},(_,i)=>{let d=start+i,s=fromDay(d),off=dow(d)===0||dow(d)===6,h=isHoliday(d);return `<div class="day-cell ${off?'weekend':''} ${h?'holiday':''} ${s===today()?'today':''}" data-date="${s}" title="${fullD(s)} · Double-click for milestone">${new Date(d*DAY).getUTCDate()}</div>`}).join('')}</div>`}
 else if(scale==='week')header=timeBand(grouping(start,days,'month'),'upper')+timeBand(grouping(start,days,'week'),'lower');
 else if(scale==='month')header=timeBand(grouping(start,days,'year'),'upper')+timeBand(grouping(start,days,'month'),'lower');
 else if(scale==='quarter')header=timeBand(grouping(start,days,'year'),'upper')+timeBand(grouping(start,days,'quarter'),'lower');
 else header=timeBand(grouping(start,days,'decade'),'upper')+timeBand(grouping(start,days,'year'),'lower');
 return `<div class="gantt-header scale-${scale}"><div class="gantt-corner"><div><strong>FEATURE / WORK ITEM</strong><small>${isFiltered()?'Filtered view':data.tasks.length+' work items'}</small></div><button class="table-add-feature" data-action="open-feature">${icon('plus',13)} Add feature</button></div><div class="calendar-head" style="width:${days*cell}px">${header}</div></div>`;
}
function leftPct(n){return (n-asDay(view.rangeStart))*view.zoom}
function widthSpan(start,end,fraction=1){return Math.max(2,(end-start+fraction)*view.zoom)}
function shades(pid){let start=asDay(view.rangeStart),end=start+view.days,cell=view.zoom,out='';
 // In wider planning horizons do not render thousands of tiny weekend bands.
 if(view.scale==='day'||view.scale==='week')for(let n=start;n<end;n++){
  let weekend=dow(n)===0||dow(n)===6,holiday=isHoliday(n);
  if(weekend||holiday)out+=`<div class="shade ${holiday?'holiday':'weekend'}" style="left:${(n-start)*cell}px;width:${cell}px" title="${holiday?esc(data.holidays.find(h=>h.date===fromDay(n))?.name):'Weekend'}"></div>`;
 }
 if(pid)for(const leave of data.leave.filter(l=>l.person===pid)){
  let first=Math.max(start,asDay(leave.from)),last=Math.min(end-1,asDay(leave.to));if(first>last)continue;
  out+=`<div class="shade leave" style="left:${(first-start)*cell}px;width:${Math.max(2,(last-first+1)*cell)}px" title="${esc((getPerson(pid)?.name||'')+' · '+leave.type)}"></div>`;
 }
 return out;
}
function rowGrip(kind,item){return `<button class="row-grip" data-action="move-row-menu" data-row-drag="${kind}" data-id="${item.id}" aria-label="Move ${esc(item.title)}${kind==='task'?' · '+esc(roleById(item.roleId)?.name||item.platform):''}" title="Drag to reorder${kind==='task'?' or change parent epic':''}. Click for move options.">${icon('grip',13)}</button>`}
function movePositionOptions(kind,id,parentId){
 const rows=kind==='feature'?data.features:data.tasks.filter(t=>t.featureId===parentId);
 return rows.filter(item=>item.id!==id).map(item=>`<option value="${item.id}">Before ${esc(item.title)}${kind==='task'?' · '+esc(roleById(item.roleId)?.name||item.platform):''}</option>`).join('')+'<option value="" selected>At the end</option>';
}
let rowScrollFrame=0;
function clearRowDrop(){ $$('.row-drop-before,.row-drop-after,.row-drop-inside').forEach(row=>row.classList.remove('row-drop-before','row-drop-after','row-drop-inside')); }
function rowDropAt(d){
 clearRowDrop();d.move=null;
 const scroller=$('#ganttScroller');if(!scroller)return;
 const bounds=scroller.getBoundingClientRect();
 if(d.x<bounds.left||d.x>bounds.right||d.y<bounds.top||d.y>bounds.bottom)return;
 const row=document.elementFromPoint(d.x,d.y)?.closest('[data-row-feature],[data-row-task]');if(!row)return;
 let targetKind=row.dataset.rowFeature?'feature':'task',targetId=row.dataset.rowFeature||row.dataset.rowTask;
 const rect=row.getBoundingClientRect();let placement=d.kind==='task'&&targetKind==='feature'?'inside':d.y<rect.top+rect.height/2?'before':'after';
 if(d.kind==='feature'&&targetKind==='task'){
  targetId=getTask(targetId)?.featureId;targetKind='feature';
 }
 if(d.kind===targetKind&&d.id===targetId)return;
 d.move={kind:d.kind,id:d.id,targetKind,targetId,placement};
 const highlight=d.kind==='feature'?$(`[data-row-feature="${targetId}"]`):row;
 // After an epic means after its complete visible group.
 let edge=highlight;
 if(d.kind==='feature'&&placement==='after')edge=$$(`[data-parent-feature="${targetId}"]`).at(-1)||highlight;
 edge?.classList.add('row-drop-'+placement);
 const parent=targetKind==='feature'?getFeature(targetId):getFeature(getTask(targetId)?.featureId);
 d.ghost.textContent=d.kind==='task'?'Move into '+(parent?.title||'epic')+' · '+placement:'Move epic and its work items · '+placement+' '+(parent?.title||'');
}
function scrollRowDrag(){
 const d=view.rowDrag;if(!d?.moved){rowScrollFrame=0;return;}
 const scroller=$('#ganttScroller');if(scroller){const r=scroller.getBoundingClientRect();
  const amount=d.y<r.top+60?-Math.min(16,(r.top+60-d.y)/3):d.y>r.bottom-45?Math.min(16,(d.y-r.bottom+45)/3):0;
  if(amount&&d.x>=r.left&&d.x<=r.right){scroller.scrollTop+=amount;rowDropAt(d);}
 }
 rowScrollFrame=requestAnimationFrame(scrollRowDrag);
}
function endRowDrag(){
 const d=view.rowDrag;view.rowDrag=null;cancelAnimationFrame(rowScrollFrame);rowScrollFrame=0;
 d?.ghost?.remove();$$('.row-drag-source').forEach(row=>row.classList.remove('row-drag-source'));clearRowDrop();root.classList.remove('row-dragging');return d;
}
function updateRowDrag(e){
 const d=view.rowDrag;if(!d)return;d.x=e.clientX;d.y=e.clientY;
 if(!d.moved&&Math.hypot(d.x-d.startX,d.y-d.startY)<=5)return;
 e.preventDefault();
 if(!d.moved){
  d.moved=true;root.classList.add('row-dragging');
  const selector=d.kind==='feature'?`[data-row-feature="${d.id}"],[data-parent-feature="${d.id}"]`:`[data-row-task="${d.id}"]`;
  $$(selector).forEach(row=>row.classList.add('row-drag-source'));
  d.ghost=document.createElement('div');d.ghost.className='row-drag-ghost';d.ghost.setAttribute('role','status');root.append(d.ghost);
  rowScrollFrame=requestAnimationFrame(scrollRowDrag);
 }
 d.ghost.style.left=Math.min(d.x+14,window.innerWidth-270)+'px';d.ghost.style.top=Math.min(d.y+16,window.innerHeight-60)+'px';rowDropAt(d);
}
function featureRow(f,visibleCount=null){let info=computed.featureInfo[f.id],taskList=data.tasks.filter(t=>t.featureId===f.id),count=taskList.length,effort=featureEffort(f,taskList),status=info.allDone?'done':info.blocked?'hold':info.atRisk?'risk':'ok';
 let mix=featureBreakdown(f,info);let text=info.end!==null?dmy(fromDay(info.end)):'TBD';let pills=info.blocked?'<span class="status-badge hold">Uncertain</span>':info.atRisk?'<span class="status-badge risk">At risk</span>':'';
 let bar='';if(info.end!==null){let l=leftPct(info.start),w=widthSpan(info.start,info.end,info.endFraction??1);bar=`<div class="feature-bar ${info.atRisk?'risk':''} ${count===0?'empty':''}" style="left:${l}px;width:${w}px;--color:${f.color}" data-action="drawer-feature" data-id="${f.id}" title="${esc(f.title)} · ${String(effort.total)}d effort · ${info.end!==null?calendarSpan(info):0} calendar days · Average capacity mix across active work items">${capacityBand(mix)}<span class="bar-txt">${esc(f.title)} · ${text}</span></div>`}
 else if(!count){let l=leftPct(info.start),w=widthSpan(info.start,asDay(f.baseline));bar=`<div class="feature-bar empty" style="left:${l}px;width:${w}px" data-action="open-story" data-id="${f.id}" title="Add user story">+ Add user story · target ${dmy(f.baseline)}</div>`}
 else if(info.blocked)bar=`<div class="bar-placeholder" style="left:${Math.max(0,leftPct(info.start))}px">${icon('pause',13)} Awaiting resumption · TBD</div>`;
 return `<div class="gantt-row feature" data-row-feature="${f.id}"><div class="meta">${rowGrip('feature',f)}<button class="chevron" data-action="collapse" data-id="${f.id}" title="Collapse / expand">${icon(f.collapsed?'chevron':'chevrondown',14)}</button><span class="feature-icon" style="background:${f.color}1d;color:${f.color}">${icon('grid',15)}</span><div class="work-name" data-action="drawer-feature" data-id="${f.id}"><strong>${esc(f.title)}</strong><small title="${String(effort.total)} work days of effort${effort.manual?' (manual estimate)':' from work items'} · Baseline ${dmy(f.baseline)}">${visibleCount!==null?`${visibleCount} of ${count} tasks`:`${count} tasks`} · <span data-feature-effort="${f.id}">${String(effort.total)}d ${effort.manual?'manual ':''}effort</span>${info.end!==null?` · ${calendarSpan(info)}d calendar`: ""} · Baseline ${dmy(f.baseline)}</small></div>${pills}<span class="meta-mini">${text}</span><button class="more-button story-add-button" data-action="open-story" data-id="${f.id}" title="Add user story" aria-label="Add user story to ${esc(f.title)}">${icon('plus',14)}</button></div><div class="track">${shades(null)}${bar}</div></div>`}
function inlineAssignee(t){const label=`Assignee for ${t.title} · ${roleById(t.roleId)?.name||t.platform}`;return `<label class="inline-assignee" title="${esc(label+' · '+(getPerson(t.assignee)?.name||'Unassigned'))}">${personAvatar(t.assignee)}${icon('chevrondown',9)}<select data-row-assignee="${t.id}" aria-label="${esc(label)}"><option value="">Unassigned</option>${matchingAssignees(data,t).map(person=>`<option value="${person.id}" ${person.id===t.assignee?'selected':''}>${esc(person.name)}</option>`).join('')}</select></label>`}
function taskRow(t){let info=computed.schedule[t.id],mix=taskBreakdown(t),conf=computed.conflicts[t.id]||[],none=!t.assignee;
 let timing=computed.dependencyConflicts[t.id]||[];let status=t.status==='hold'?'hold':info.blocked?'blocked':t.status==='done'?'done':'';
 let l=leftPct(info.start??asDay(t.start)),width=info.end!==null?widthSpan(info.start,info.end,info.endFraction??1):Math.max(2*view.zoom,74);
 let bar=info.end!==null?`<div class="task-bar ${esc(String(t.platform).toLowerCase().replace(/[^a-z0-9_-]/g,'-'))} ${status} ${info.shortfall?'date-shortfall':''}" style="left:${l}px;width:${width}px" draggable="false" data-task="${t.id}" data-action="drawer-task" data-id="${t.id}" title="${esc(t.title)} · ${String(t.effort)}d effort · ${info.start!==null?dmy(fromDay(info.start)):'—'}–${dmy(fromDay(info.end))} · ${esc(breakdownText(mix))}">${capacityBand(mix)}<span class="bar-txt">${esc(t.title)}</span>${conf.length?`${icon('warning',11)}`:''}<span class="bar-tail">${String(t.effort)}d${width>170?` effort · ${calendarSpan(info)}d calendar`:width>90?` · ${calendarSpan(info)}d cal`: ""}</span></div>`:`<div class="task-bar ${status}" style="left:${l}px;width:${width}px" data-task="${t.id}" data-action="drawer-task" data-id="${t.id}" title="${esc(t.title)}"><span>${status==='hold'?'⏸ Paused':'⌛ Blocked'}</span></div>`;
 let helper=t.status==='hold'?'Paused':info.blocked?'Blocked':info.end!==null?dmy(fromDay(info.end)):'—';
 let circle=t.status==='done'?`<span class="status-circle done">${icon('check',10)}</span>`:t.status==='hold'?`<span class="status-circle hold">${icon('pause',10)}</span>`:`<span class="status-circle ${t.status==='progress'?'progress':''}"></span>`;
 let bad=conf.length?`<span title="Conflicting capacity on ${conf.length} day(s)" style="color:#e27f8e">${icon('warning',13)}</span>`:'';
 return `<div class="gantt-row" data-row-task="${t.id}" data-parent-feature="${t.featureId}"><div class="meta">${rowGrip('task',t)}<span class="task-indent"></span>${circle}<div class="work-name" data-action="drawer-task" data-id="${t.id}"><strong>${esc(t.title)}</strong><small>${esc(roleById(t.roleId)?.name||t.platform)} · ${String(t.effort)}d effort${info.end!==null?` · ${calendarSpan(info)}d calendar`: ""} ${t.dependsOn?.length?' · '+t.dependsOn.length+' dep.':''}</small></div>${bad}${inlineAssignee(t)}<span class="meta-mini">${helper}</span><button class="more-button" data-action="drawer-task" data-id="${t.id}" title="Edit task">${icon('more',15)}</button></div><div class="track">${shades(t.assignee)}${view.scale==='day'||view.scale==='week'?conf.map(s=>`<div class="shade overload" style="left:${leftPct(asDay(s))}px;width:${view.zoom}px" title="Overbooked: ${s}"></div>`).join(''):''}${bar}${dependencyHandles(t,l,width)}</div></div>`}
function dependencyHandles(t,left,width){return `<button class="dependency-handle from" style="left:${left+width+2}px" data-action="link-from" data-id="${t.id}" aria-label="Connect from ${esc(t.title)} · ${esc(t.platform)}" title="Drag to a dependent work item">○</button><button class="dependency-handle to" style="left:${Math.max(2,left-12)}px" data-link-anchor="${left}" data-action="link-to" data-id="${t.id}" aria-label="Connect to ${esc(t.title)} · ${esc(t.platform)}" title="Link a predecessor; date movement follows General settings">○</button>`}
function addMapDependency(sourceId,targetId){
 const target=getTask(targetId),source=getTask(sourceId);view.linkSource=null;view.linkDrag=null;
 if(!source||!target){render();return;}
 const next=[...new Set([...(target.dependsOn||[]),sourceId])];
 if(sourceId===targetId||cycleCheck(targetId,next)){render();notify('Circular dependencies are not allowed');return;}
 if(target.dependsOn?.includes(sourceId)){render();notify('This dependency already exists');return;}
 change(()=>target.dependsOn=next,'Dependency added');
}
function removeMapDependency(){const selected=view.selectedLink;if(!selected)return;const task=getTask(selected.to);view.selectedLink=null;if(task)change(()=>task.dependsOn=task.dependsOn.filter(id=>id!==selected.from),'Dependency removed');}
function syncLinkTargets(){const scroll=$('#ganttScroller')?.scrollLeft||0;$$('[data-link-anchor]').forEach(node=>node.style.left=Math.max(scroll+2,Number(node.dataset.linkAnchor)-12)+'px');}
function drawDependencyLines(){
 const canvas=$('.gantt-canvas'),svg=$('.dependency-layer');if(!canvas||!svg)return;
 canvas.classList.toggle('linking',Boolean(view.linkSource||view.linkDrag));
 syncLinkTargets();const base=canvas.getBoundingClientRect(),meta=$('.gantt-corner')?.getBoundingClientRect().width||0;
 const width=canvas.clientWidth,height=canvas.clientHeight;
 svg.setAttribute('viewBox',`0 0 ${width} ${height}`);svg.style.width=width+'px';svg.style.height=height+'px';
 const anchors=new Map();$$('.task-bar[data-task]').forEach(bar=>{const rect=bar.getBoundingClientRect();anchors.set(bar.dataset.task,{left:rect.left-base.left,right:rect.right-base.left,y:rect.top-base.top+rect.height/2});});
 let html=`<defs><marker id="orbit-arrowhead" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L0,6 L6,3 z" fill="#8376c9"/></marker><marker id="orbit-arrowhead-warning" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L0,6 L6,3 z" fill="#c78a34"/></marker><clipPath id="orbit-link-clip"><rect x="${meta}" y="0" width="${width-meta}" height="${height}"/></clipPath></defs><g clip-path="url(#orbit-link-clip)">`;
 for(const target of data.tasks){const end=anchors.get(target.id);if(!end)continue;for(const id of target.dependsOn||[]){const start=anchors.get(id);if(!start)continue;const warning=(computed.dependencyConflicts[target.id]||[]).includes(id);const selected=view.selectedLink?.from===id&&view.selectedLink?.to===target.id;html+=`<path class="dependency-edge ${warning?'timing-warning':''} ${selected?'selected':''}" data-dependency-edge data-action="select-link" data-from="${id}" data-to="${target.id}" d="${dependencyPath({x:start.right+3,y:start.y},{x:end.left-3,y:end.y})}" marker-end="url(#${warning?'orbit-arrowhead-warning':'orbit-arrowhead'})" fill="none" tabindex="0" role="button" aria-label="Dependency: ${esc(getTask(id)?.title)} → ${esc(target.title)}"/>`;}}
 const drag=view.linkDrag,source=anchors.get(drag?.source||view.linkSource);if(drag&&source)html+=`<path class="dependency-preview" d="${dependencyPath({x:source.right+3,y:source.y},{x:drag.x-base.left,y:drag.y-base.top})}" fill="none"/>`;
 html+='</g>';const holder=document.createElement('div');holder.innerHTML=sanitizeMarkup(`<svg xmlns="http://www.w3.org/2000/svg">${html}</svg>`);const safe=holder.querySelector('svg');svg.replaceChildren(...(safe?[...safe.childNodes]:[]));
}
function ganttOverlay(){let arr=[],range=asDay(view.rangeStart),max=range+view.days,cell=view.zoom,meta=350; // CSS --meta-w handles responsive
 if(asDay(today())>=range&&asDay(today())<max){let left=`calc(var(--meta-w) + ${leftPct(asDay(today()))+cell/2}px)`;arr.push(`<div class="today-line" style="left:${left}"></div><div class="today-tag" style="left:${left}">Today</div>`)}
 for(let m of data.milestones){let day=asDay(m.date);if(day<range||day>=max)continue;let missed=m.featureIds?.some(id=>{let f=computed.featureInfo[id];return f&&f.end!==null&&f.end>day})||false;let x=`calc(var(--meta-w) + ${leftPct(day)+cell/2}px)`;
 arr.push(`<div class="milestone-line ${missed?'risk':''}" style="left:${x};border-color:${missed?'#ed7d89':m.color}"></div><button class="milestone-pin ${missed?'risk':''}" style="left:${x}" data-action="drawer-milestone" data-id="${m.id}" title="${esc(m.title)} · ${fullD(m.date)} · Drag to move">${icon('flag',11)} <span>${esc(m.title)}</span></button>`)}
 return arr.join('')}
function renderGantt(){
 let list=data.features.filter(f=>(!view.showOnlyRisks||computed.featureInfo[f.id].atRisk)&&(!isFiltered()||matchingTasks(f.id).length));
 let rows=list.flatMap(f=>{let tasks=matchingTasks(f.id);return [featureRow(f,isFiltered()?tasks.length:null),...(f.collapsed?[]:tasks.map(taskRow))]});
 let filtered=isFiltered()||view.showOnlyRisks;
 let empty=`<div class="empty-message"><h3>${filtered?'No matching work items':'Your roadmap is ready'}</h3><p>${filtered?'Try clearing the filters or choosing another team member.':'Create your first feature to begin planning.'}</p>${isFiltered()?'<button class="btn sm" data-action="clear-filters">Clear filters</button>':''}</div>`;
 return `<div class="gantt-scroller" id="ganttScroller" tabindex="0" role="region" aria-label="Roadmap timeline. Scroll left or right to browse dates."><div class="gantt-canvas scale-${view.scale}" data-range-start="${view.rangeStart}" data-range-days="${view.days}" style="--total-days:${view.days};--cell:${view.zoom}px;min-width:calc(var(--meta-w) + ${view.days*view.zoom}px)">${headings()}${rows.join('')||empty}${ganttOverlay()}<svg class="dependency-layer" aria-label="Work item dependencies"></svg></div></div>${capacityLegend()}${view.linkSource?'<div class="map-link-notice" role="status">Choose a target connector. Escape cancels.</div>':''}${view.selectedLink?'<button class="map-link-remove btn sm danger" data-action="remove-link">Remove selected dependency</button>':''}`;
}
function teamView(){
 return `<div class="team-layout">
 <section class="card panel-body"><div class="split-head"><div><h2 class="panel-title">Team members <span class="soft-tag">${data.people.length}</span></h2><p class="panel-sub">Names, roles and workstreams are maintained here.</p></div><button class="btn sm primary" data-action="open-team-member">${icon('plus')} Add member</button></div>
 <div class="team-list">${data.people.map(p=>{let r=roleById(p.roleId),assigned=data.tasks.filter(t=>t.assignee===p.id).length;return `<div class="team-row"><div class="person-cell">${personAvatar(p.id,'avatar')}<div><strong>${esc(p.name)}</strong><small>${esc(r?.name||p.role||'No role')} · ${esc(r?.platform||p.platform||'Unassigned')}</small></div></div><span class="soft-tag">${assigned} work items</span><div class="team-actions"><button class="mini-btn" data-action="edit-team-member" data-id="${p.id}">Edit</button><button class="icon-action" data-action="delete-team-member" data-id="${p.id}" title="Remove member">${icon('trash',15)}</button></div></div>`}).join('')||'<div class="grouped-note">No team members yet. Start by creating a role, then add your first teammate.</div>'}</div>
 </section><section class="card panel-body"><div class="split-head"><div><h2 class="panel-title">Roles & workstreams <span class="soft-tag">${data.roles.length}</span></h2><p class="panel-sub">Every role maps to a platform shown on work items.</p></div><button class="btn sm" data-action="open-role">${icon('plus')} Add role</button></div><div class="team-list">${data.roles.map(r=>`<div class="team-row"><div class="team-role-icon">${icon('users',17)}</div><div class="team-role-name"><strong>${esc(r.name)}</strong><small>Workstream: ${esc(r.platform)}</small></div><span class="soft-tag">${roleAssignmentCount(r.id)} people</span><div class="team-actions"><button class="mini-btn" data-action="edit-role" data-id="${r.id}">Edit</button><button class="icon-action" data-action="delete-role" data-id="${r.id}" title="Remove role">${icon('trash',15)}</button></div></div>`).join('')||'<div class="grouped-note">Create a role, e.g. iOS Engineer → iOS.</div>'}</div>
 <div class="grouped-note" style="margin-top:16px"><strong>How it works</strong><p>1. Create a role and link it to a workstream (Backend, iOS, Design, etc.). 2. Add people with that role. 3. Work item Platform shows those workstreams, and Assignee shows only matching teammates. Meetings and time off follow each person.</p></div>
 </section></div>`;
}
function availabilityView(){let ordered=[...data.leave].sort((a,b)=>a.from.localeCompare(b.from));return `<div class="capacity-layout"><section class="card panel-body"><div class="split-head"><div><h2 class="panel-title">Team time off</h2><p class="panel-sub">Vacation, sick days and personal leave block scheduling automatically.</p></div><button class="btn sm" data-action="open-leave">${icon('plus')} Add</button></div><div class="availability-list">${ordered.map(l=>`<div class="availability-card"><div class="leave-icon ${l.type==='sick'?'sick':''}">${icon(l.type==='sick'?'heart':l.type==='vacation'?'suitcase':'calendar')}</div><div class="detail"><strong>${esc(getPerson(l.person)?.name||'Unknown')} · ${l.type==='vacation'?'Vacation':l.type==='sick'?'Sick leave':'Day off'}</strong><small>${fullD(l.from)} ${l.from!==l.to?' – '+fullD(l.to):''} · ${workdayCount(l.from,l.to)} calendar workdays${l.note?' · '+esc(l.note):''}</small></div><button class="icon-action" data-action="edit-leave" data-id="${l.id}" title="Edit">${icon('edit')}</button><button class="icon-action" data-action="delete-leave" data-id="${l.id}" title="Delete">${icon('trash')}</button></div>`).join('')||'<div class="empty-message">No planned absences.</div>'}</div></section><div style="display:grid;gap:15px"><section class="card panel-body"><h2 class="panel-title">Workweek & holidays</h2><p class="panel-sub">Ukraine · Monday–Friday · ${data.settings.workHours} hours/day</p><div class="switch-row"><div><strong>Exclude public holidays</strong><small>Use holiday calendar as non-working days</small></div><button class="switch ${data.settings.observeHolidays?'on':''}" data-action="holiday-switch" aria-label="Toggle holidays"></button></div><div class="notice warn" style="margin-top:13px">Under martial law, statutory Ukrainian holidays may not be mandatory days off. Configure this switch to match your company policy.</div><h3 style="font-size:12px;margin:20px 0 8px">Custom holiday dates</h3>${data.holidays.map(h=>`<div class="metric-row"><span>${dmy(h.date)} · ${esc(h.name)}</span><button class="icon-action" data-action="delete-holiday" data-id="${h.date}" title="Delete">${icon('trash',14)}</button></div>`).join('')}<button class="btn sm" data-action="open-holiday">${icon('plus')} Add holiday</button></section><section class="card panel-body"><h3 class="panel-title">Planning rules</h3><div class="metric-row"><span>Default working days</span><strong>Mon–Fri</strong></div><div class="metric-row"><span>Personal leave</span><strong>Always excluded</strong></div><div class="metric-row"><span>Dependent tasks</span><strong>${data.settings.autoShiftDependencies?'Auto-shift enabled':'Manual placement'}</strong></div><div class="metric-row"><span>Conflicting parallel tasks</span><strong>Flag, don't reorder</strong></div></section></div></div>`}
function milestoneView(){return `<section class="card panel-body"><div class="split-head"><div><h2 class="panel-title">Release & stakeholder dates</h2><p class="panel-sub">Milestones overlay every row of the timeline. Drag a pin to move it; the date never forces tasks to shift.</p></div><button class="btn sm" data-action="open-milestone">${icon('plus')} Add milestone</button></div><div class="milestone-list">${[...data.milestones].sort((a,b)=>a.date.localeCompare(b.date)).map(m=>{let missed=m.featureIds?.some(id=>computed.featureInfo[id]?.end!==null&&computed.featureInfo[id]?.end>asDay(m.date));return `<div class="milestone-card"><div class="milestone-icon">${icon('flag')}</div><div class="detail"><strong>${esc(m.title)}</strong><small>${fullD(m.date)} · ${m.featureIds?.length||0} linked features</small></div>${missed?'<span class="status-badge risk">Deadline risk</span>':'<span class="status-badge muted">On timeline</span>'}<button class="btn sm" data-action="drawer-milestone" data-id="${m.id}">${icon('edit')} Edit</button><button class="icon-action" data-action="delete-milestone" data-id="${m.id}">${icon('trash')}</button></div>`}).join('')||'<div class="empty-message">No milestones yet.</div>'}</div><div class="grouped-note"><strong>Tip: create directly on the timeline</strong><p>Return to Roadmap and double-click any date in the top date header. Add a title, then link relevant features to highlight potential release misses.</p></div></section>`}
function drawerMarkup(){if(!view.drawer)return '';let d=view.drawer,body='',heading='',sub='';
 if(d.type==='task'){let t=getTask(d.id);if(!t)return '';heading=t.title;sub='WORK ITEM · '+(roleById(t.roleId)?.name||t.platform);body=taskInspector(t)}
 else if(d.type==='feature'){let f=getFeature(d.id);if(!f)return '';heading=f.title;sub='FEATURE · PRODUCT ROADMAP';body=featureInspector(f)}
 else if(d.type==='milestone'){let m=data.milestones.find(m=>m.id===d.id);if(!m)return '';heading=m.title;sub='MILESTONE · DATE MARKER';body=milestoneInspector(m)}
 return `<div class="drawer-wrap"><div class="drawer-backdrop" data-action="close-drawer"></div><aside class="drawer"><div class="drawer-header"><div><div class="eyebrow">${esc(sub)}</div><h2>${esc(heading)}</h2></div><button class="icon-action" data-action="close-drawer" title="Close">${icon('close',20)}</button></div><div class="drawer-content">${body}</div></aside></div>`}
function taskInspector(t){let s=computed.schedule[t.id],deps=data.tasks.filter(x=>x.id!==t.id),conf=computed.conflicts[t.id]||[],holidayNum=(t.status==='hold'||s.end===null)?null:calendarSpan(s);
 let timing=computed.dependencyConflicts[t.id]||[];let predicted=t.status==='hold'?'Paused':s.blocked?'Blocked':s.end!==null?fullD(fromDay(s.end)):'TBD';let status=selectField('Status','taskStatus',Object.entries(statusLabels),t.status);
 let dependencyHtml=deps.length?deps.map(x=>`<label class="checkline"><input type="checkbox" aria-label="Depend on ${esc(x.title)} · ${esc(x.platform)}" data-dependency="${x.id}" ${t.dependsOn?.includes(x.id)?'checked':''}><span>${esc(x.title)} · ${esc(x.platform)}</span><small style="color:#abb2c1"> · ${esc(getFeature(x.featureId)?.title||'')}</small></label>`).join(''):'No other tasks available';
 return `<div class="drawer-section"><div class="drawer-stat"><span>${icon('clock',14)} Forecast</span><span>${predicted}</span></div>${conf.length?`<div class="notice warn" style="margin-bottom:12px">${icon('warning',14)} Capacity conflict on ${conf.length} day(s). Check overlapping assignments.</div>`:''}${timing.length&&!data.settings.autoShiftDependencies?'<div class="notice warn">Dependency dates conflict. Auto-shift is off; your chosen dates are preserved.</div>':''}${s.blocked?`<div class="notice warn" style="margin-bottom:12px">${icon('lock',14)} Resolve paused work or date/capacity conflicts in its dependencies before forecasting this item.</div>`:''}<div class="field"> <label>Task title</label><input data-update-task="title" value="${esc(t.title)}"></div>${status}<div class="field-grid">${numberField('Pure effort (days)','taskEffort',t.effort,.5,3650,.5)}${numberField('Remaining effort (days)','taskRemaining',t.remaining??t.effort,0,3650,.5)}</div><div class="field-grid"><div class="field"><label>Team member</label><select data-update-task="assignee">${personOptions(t.assignee,true,t.platform,t.roleId)}</select></div>${selectField('Platform','taskPlatform',platformChoices(t.platform),t.platform)}</div>${selectField('Role','taskRole',[['','Any role on platform'],...data.roles.map(r=>[r.id,r.name])],t.roleId||'')}${scheduleDateFields(t,s,'task')}<div class="notice">${icon('info',13)} <span>Elapsed span: <strong>${holidayNum??'—'} calendar days</strong>. Estimate includes all work: development, fixes, tests and review. Meetings and days off extend the calendar duration.</span></div></div>${capacityDetails(t)}<div class="drawer-section"><div class="section-head">Dependencies <span class="soft-tag">${t.dependsOn?.length||0} selected</span></div><div style="max-height:155px;overflow:auto">${dependencyHtml}</div><small style="font-size:10px;color:#a5adba">${data.settings.autoShiftDependencies?'Auto-shift is enabled for this project.':'Links only: move dates yourself, or enable auto-shift in General settings.'} Circular dependencies are not allowed.</small></div><div class="drawer-section"><div class="section-head">Quick actions</div><div style="display:flex;gap:7px;flex-wrap:wrap">${t.status==='hold'?`<button class="btn sm primary" data-action="quick-resume" data-id="${t.id}">${icon('play',12)} Resume task</button>`:`<button class="btn sm" data-action="quick-hold" data-id="${t.id}">${icon('pause',12)} Put on hold</button>`}<button class="btn sm" data-action="duplicate-task" data-id="${t.id}">${icon('copy',12)} Duplicate</button><button class="btn sm danger" data-action="delete-task" data-id="${t.id}">${icon('trash',12)} Delete</button></div></div>`}
function featureInspector(f){let s=computed.featureInfo[f.id],children=data.tasks.filter(t=>t.featureId===f.id),effort=featureEffort(f,children),status=s.allDone?'All tasks done':s.blocked?'Uncertain · on hold / blocked':s.atRisk?'At risk':'On track';
 return `<div class="drawer-section"><div class="drawer-stat"><span>Current forecast</span><span>${s.end!==null?fullD(fromDay(s.end)):'TBD'}</span></div><div class="notice ${s.atRisk?'warn':'good'}" style="margin-bottom:12px">${s.blocked?'One or more tasks are blocked / paused. Forecast has no reliable end date.':s.atRisk?(s.delta>0?`Forecast is ${s.delta} calendar days past the baseline.`:'Work exceeds the selected dates or available capacity.'):'This feature is currently within its baseline.'}</div><div class="field"><label>Feature name</label><input data-update-feature="title" value="${esc(f.title)}"></div><div class="field"><label>Description</label><textarea rows="3" data-update-feature="description">${esc(f.description||'')}</textarea></div>${scheduleDateFields(f,s,'feature')}${dateField('Baseline deadline','featureBaseline',f.baseline)}<div class="metric-row"><span>Status</span><span class="status-badge ${s.atRisk?'risk':s.allDone?'done':'muted'}">${esc(status)}</span></div><div class="metric-row"><span>Child tasks</span><strong>${children.length}</strong></div><div class="drawer-stat"><span>Total effort</span><strong>${String(effort.total)}d</strong></div>${selectField('Effort estimate','featureEffortMode',[['automatic','Sum of work items'],['manual','Manual estimate']],effort.manual?'manual':'automatic')}${effort.manual?numberField('Manual total effort (days)','featureEffort',effort.total,0,10950000,'.1'):''}<div class="metric-row"><span>Work items combined</span><strong>${String(effort.calculated)}d</strong></div><p class="panel-sub">Effort is measured in work days. Delivery dates follow the work-item schedule.</p></div><div class="drawer-section"><div class="section-head">Work breakdown<div class="work-breakdown-actions"><button class="mini-btn" data-action="open-story" data-id="${f.id}">+ Add user story</button><button class="mini-btn" data-action="open-task" data-id="${f.id}">+ Add task</button></div></div>${children.map(t=>`<div class="metric-row" style="cursor:pointer" data-action="drawer-task" data-id="${t.id}"><span>${esc(t.title)}<small class="breakdown-platform">${esc(t.platform)} · ${String(t.effort)}d</small></span><span>${personAvatar(t.assignee)} ${icon('chevron',11)}</span></div>`).join('')||'<div class="panel-sub">No tasks yet. Click Add task to begin.</div>'}</div><div class="drawer-section"><button class="btn danger sm" data-action="delete-feature" data-id="${f.id}">${icon('trash')} Delete feature & tasks</button></div>`}
function milestoneInspector(m){let risk=(m.featureIds||[]).map(id=>({f:getFeature(id),s:computed.featureInfo[id]})).filter(x=>x.f&&x.s&&x.s.end!==null&&x.s.end>asDay(m.date));return `<div class="drawer-section"><div class="field"><label>Milestone name</label><input data-update-milestone="title" value="${esc(m.title)}"></div>${dateField('Date','milestoneDate',m.date)}<div class="field"><label>Marker color</label><input type="color" id="milestoneColor" value="${esc(m.color)}" style="height:43px;padding:5px"></div><div class="section-head">Linked features</div>${data.features.map(f=>`<label class="checkline"><input type="checkbox" data-milestone-feature="${f.id}" ${m.featureIds?.includes(f.id)?'checked':''}>${esc(f.title)}</label>`).join('')}<div style="margin-top:14px;display:flex;gap:9px"><button class="btn primary" data-action="save-milestone" data-id="${m.id}">${icon('save')} Save milestone</button><button class="btn danger" data-action="delete-milestone" data-id="${m.id}">${icon('trash')}</button></div></div><div class="drawer-section"><div class="section-head">Milestone health</div>${risk.length?`<div class="notice warn">${risk.length} linked feature(s) forecast beyond this marker: ${risk.map(x=>esc(x.f.title)).join(', ')}</div>`:'<div class="notice good">No linked feature currently misses this milestone.</div>'}</div>`}
function modalMarkup(){if(!view.modal)return '';let m=view.modal,content='',title='',subtitle='',footer='',wide=false;
 const dismiss=`<button type="button" class="btn" data-action="close-modal">Cancel</button>`;
 const submit=(name)=>`${dismiss}<button type="submit" class="btn primary">${icon('check')} ${name}</button>`;
 if(m.type==='move-row'){
 const item=m.kind==='feature'?getFeature(m.id):getTask(m.id);if(!item)return '';
 title='Move item';subtitle=m.kind==='feature'?'The epic moves with all its work items. Dates stay unchanged.':'Choose the parent epic and position. Dates, estimates and dependencies stay unchanged.';
 content=`<form id="modalForm" data-form="move-row"><p class="panel-sub">${esc(item.title)}</p>${m.kind==='task'?selectField('Parent epic','moveParent',data.features.map(f=>[f.id,f.title]),item.featureId):''}<div class="field"><label for="movePosition">Position</label><select id="movePosition" name="movePosition">${movePositionOptions(m.kind,m.id,item.featureId)}</select></div><div class="dialog-foot">${submit('Move item')}</div></form>`;
 }else if(m.type==='new-project'){
 title='Create a new project';subtitle='Each project has its own roadmap, team, roles, and meeting schedules.';
 content=`<form id="modalForm" data-form="new-project">${textField('Project name','projectName','','required autofocus maxlength="100" placeholder="e.g. Mobile app 2027"')}
  <div class="copy-setup-box"><div class="copy-setup-heading">${icon('copy',16)} <strong>Reuse setup from an existing project</strong><span class="soft-tag">Optional</span></div>
  <div class="field" style="margin:14px 0 7px"><label for="newProjectSource">Copy from</label><select name="sourceProject" id="newProjectSource"><option value="">Start from scratch</option>${workspace.projects.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${p.data.people.length} people, ${(p.data.meetings||[]).length} meetings</option>`).join('')}</select></div>
  <div id="newProjectCopyOptions" class="copy-settings-choices" hidden><label class="checkline"><input type="checkbox" name="copyTeam" checked> ${icon('users',14)} Copy team and roles</label><label class="checkline"><input type="checkbox" name="copyMeetings" checked> ${icon('clock',14)} Copy all recurring meetings</label><small>Only setup is copied — not tasks, time off, milestones or existing features. You can review everything in the next two steps.</small></div></div>
  <div class="grouped-note"><strong>Next: quick setup</strong><p>Step 1: team and roles · Step 2: recurring meetings. Both steps are optional. Your existing projects stay intact.</p></div><div class="dialog-foot">${submit('Create & set up')}</div></form>`;
 }else if(m.type==='projects'){
 title='Your projects';subtitle='Switch between independent roadmaps, or start a new one.';
 content=`${workspace.projects.map(p=>`<div class="project-pick-row ${p.id===workspace.activeId?'is-current':''}"><span class="team-role-icon">${icon('grid',17)}</span><div class="project-pick-name"><strong>${esc(p.name)}</strong><small>${p.data.features.length} features · ${p.data.people.length} team members</small></div>${p.id===workspace.activeId?'<span class="soft-tag">Current</span>':`<button class="btn sm" data-action="switch-project" data-id="${p.id}">Open project ${icon('chevron',12)}</button>`}</div>`).join('')}<div class="dialog-foot"><button class="btn" data-action="close-modal">Close</button><button class="btn primary" data-action="new-project">${icon('plus',14)} New project</button></div>`;
 }else if(m.type==='feature'){
 title='Create a feature';subtitle='Create an epic and estimate its first user story by team.';wide=true;
 content=`<form id="modalForm" data-form="feature"><div class="field-grid">${textField('Feature name','name','', 'required maxlength="200" placeholder="e.g. Disable Rules"')}${dateField('Earliest start','start',addDays(monday(today()),7))}</div>${textField('Description','description','','maxlength="10000" placeholder="What are we delivering?"')}<div class="field-grid">${dateField('Baseline target date','baseline',addDays(monday(today()),28))}<div class="field"><label for="featureEstimate">Manual total effort (days)</label><input type="number" id="featureEstimate" name="featureEstimate" min="0" max="10950000" step=".1" placeholder="Automatic"><small>Leave blank to sum work items.</small></div></div><div class="hr"></div>${textField('First user story (optional)','storyTitle','','maxlength="200" placeholder="e.g. Add a specific rule"')}<p class="panel-sub">Leave the story name blank to use the feature name. Select no teams to start with an empty epic.</p>${storyTeamFields()}<div class="dialog-foot">${submit('Create feature')}</div></form>`;
 }else if(m.type==='story'){
 let f=getFeature(m.featureId);title='Add user story';subtitle=`Estimate work by team inside ${f?.title||'feature'}.`;wide=true;
 content=`<form id="modalForm" data-form="story">${textField('User story name','storyTitle','','required autofocus maxlength="200" placeholder="e.g. Add a specific rule"')}${dateField('Earliest start','start',f?.start||today())}${storyTeamFields()}<div class="dialog-foot">${submit('Add user story')}</div></form>`;
 }else if(m.type==='task'){
 let f=getFeature(m.featureId),defaultPlatform=platformNames()[0]||'',assignee=data.people.find(p=>p.platform===defaultPlatform)?.id||'';
 title='Add work item';subtitle=`Add a task inside ${f?.title||'feature'}.`;
 content=`<form id="modalForm" data-form="task"><div class="field"> <label>Task name</label><input name="name" placeholder="What needs to be delivered?" required autofocus></div><div class="field-grid">${selectField('Platform','platform',platformChoices(),defaultPlatform)}${numberField('Pure effort (days)','effort',2,.5,180)}</div><div class="field-grid"><div class="field"><label>Assignee</label><select name="assignee">${personOptions(assignee,true,defaultPlatform)}</select></div>${dateField('Earliest start','start',f?.start||today())}</div>${selectField('Initial status','status',Object.entries(statusLabels),'planned')}<div class="field"><label>Dependency (optional)</label><select name="dependency"><option value="">None</option>${data.tasks.filter(t=>t.featureId===m.featureId).map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('')}</select></div><div class="dialog-foot">${submit('Add task')}</div></form>`;
 }else if(m.type==='member'){
 let p=data.people.find(x=>x.id===m.id),parts=p?{first:p.firstName||p.name.split(' ')[0],last:p.lastName||p.name.split(' ').slice(1).join(' ')}:{first:'',last:''};
 title=p?'Edit team member':'Add team member';subtitle='Select a role. Platform and matching work item assignments update automatically.';
 content=`<form id="modalForm" data-form="member"><div class="field-grid">${textField('First name','firstName',parts.first,'required placeholder="e.g. Oleksandr"')}${textField('Last name','lastName',parts.last,`${p?'':'required '}placeholder="e.g. Shevchenko"`)}</div><div class="field"><label>Role</label><select name="roleId" required>${!data.roles.length?'<option value="">Create a role first</option>':roleOptions(p?.roleId||data.roles[0].id)}</select></div><div class="grouped-note"><strong>Working time</strong><p>Estimates cover all work. Recurring meetings, weekends, holidays and time off determine the calendar duration.</p></div><div class="dialog-foot"><button type="button" class="btn" data-action="go-team">Cancel</button><button type="submit" class="btn primary" ${!data.roles.length?'disabled':''}>${icon('check')} ${p?'Save changes':'Add member'}</button></div></form>`;
 }else if(m.type==='role'){
 let r=data.roles.find(x=>x.id===m.id);title=r?'Edit role':'Create a role';subtitle='A role defines what workstream a person can be assigned to.';
 content=`<form id="modalForm" data-form="role">${textField('Role name','roleName',r?.name||'','required placeholder="e.g. Android Engineer"')}${textField('Platform / workstream','platformName',r?.platform||'','required placeholder="e.g. Android" list="suggested-platforms"')}<datalist id="suggested-platforms">${platformNames().map(x=>`<option value="${esc(x)}"></option>`).join('')}</datalist><div class="grouped-note"><strong>Examples</strong><p>Backend Developer → Backend; QA Engineer → QA; iOS Developer → iOS. Multiple roles can share the same platform.</p></div><div class="dialog-foot"><button type="button" class="btn" data-action="go-team">Cancel</button><button type="submit" class="btn primary">${icon('check')} ${r?'Save role':'Create role'}</button></div></form>`;
 }else if(m.type==='leave'){
 let x=data.leave.find(l=>l.id===m.id),start=addDays(monday(today()),9);
 title=x?'Edit time off':'Add time off';subtitle='Reschedules the person’s assigned tasks and all downstream dependencies.';
 content=`<form id="modalForm" data-form="leave"><div class="field"><label>Team member</label><select name="person">${personOptions(x?.person||m.person||data.people[0]?.id)}</select></div>${selectField('Type','type',[['vacation','Vacation'],['sick','Sick leave'],['dayoff','Day off']],x?.type||'vacation')}<div class="field-grid">${dateField('From','from',x?.from||start)}${dateField('To (inclusive)','to',x?.to||addDays(start,4))}</div>${textField('Note','note',x?.note||'','placeholder="Optional"')}<div class="dialog-foot">${submit(x?'Save time off':'Add time off')}</div></form>`;
 }else if(m.type==='milestone'){
 title='Add a milestone';subtitle='A vertical date marker layered over the roadmap (not a task).';
 content=`<form id="modalForm" data-form="milestone">${textField('Milestone name','name','', 'required placeholder="e.g. Release 3.0"')}${dateField('Date','date',m.date||addDays(today(),14))}<div class="field"><label>Link features (optional)</label>${data.features.map(f=>`<label class="checkline"><input type="checkbox" name="link_${f.id}">${esc(f.title)}</label>`).join('')}</div><div class="dialog-foot">${submit('Add milestone')}</div></form>`;
 }else if(m.type==='holiday'){
 title='Add a calendar holiday';subtitle='When enabled, dates on this calendar are excluded from task schedules.';
 content=`<form id="modalForm" data-form="holiday">${textField('Holiday title','name','', 'required placeholder="e.g. Company day off"')}${dateField('Date','date',today())}<div class="dialog-foot">${submit('Add holiday')}</div></form>`;
 }else if(m.type==='settings'){
 title='General settings';subtitle=`Settings for ${currentProject()?.name||'this project'}. Other projects keep their own preferences.`;
 content=`<form id="modalForm" data-form="settings">${dependencySettingFields()}<div class="section-head" style="margin-top:20px">Working calendar</div><div class="field-grid">${numberField('Working hours / day','workHours',data.settings.workHours,1,24,1)}<div class="field"><label>Working week</label><input value="Monday – Friday" disabled></div></div><div class="switch-row"><div><strong>Account for Ukrainian public holidays</strong><small>During martial law, your actual company policy may differ.</small></div><input style="width:20px;height:20px;accent-color:#7669e6" type="checkbox" name="holidays" ${data.settings.observeHolidays?'checked':''}></div><div class="meeting-settings-entry"><div><strong>${icon('users',17)} Team & roles</strong><small>${data.people.length} members · ${data.roles.length} roles · dynamically generated work item platforms</small></div><button type="button" class="btn sm" data-action="go-team">${icon('edit')} Manage team</button></div><div class="meeting-settings-entry"><div><strong>${icon('clock',17)} Recurring meetings</strong><small>${(data.meetings||[]).filter(m=>m.enabled).length} active recurring events · deducted from the appropriate people’s capacity</small></div><button class="btn sm" type="button" data-action="manage-meetings">${icon('edit')} Manage meetings</button></div><div class="grouped-note"><strong>Roadmap data</strong><p>Private cloud storage · Export or import JSON to back up this project.</p><div style="display:flex;gap:12px;flex-wrap:wrap;margin-top:12px"><button type="button" class="btn sm" data-action="export">${icon('download')} Export JSON</button><button type="button" class="btn sm" data-action="import">${icon('upload')} Import JSON</button><input id="jsonImport" type="file" accept=".json,application/json" hidden><button type="button" class="btn sm danger" data-action="reset">Reset project</button></div></div><div class="grouped-note"><strong>Scheduling behavior</strong><p>We never auto-prioritize your tasks or change status. Task estimates include all work. Dependency behavior follows your choice above. Meetings and working calendars determine effort-based forecasts; overload is displayed without changing priorities.</p></div><div class="dialog-foot">${submit('Save settings')}</div></form>`;
 }else if(m.type==='meetings'){
 title='Recurring meetings';subtitle='Recurring meetings reduce available work time and update effort-based forecasts.';wide=true;
 content=`<div class="notice" style="margin-bottom:14px">${icon('info',15)} <div><strong>How meetings affect estimates</strong><div style="margin-top:4px">Available work time = working hours − recurring meeting hours. Estimates cover all work, including fixes and review. Overlapping meetings count once. Their daily total is rounded up to 0.5-day slots for planning; exact meeting minutes stay unchanged. Weekends, holidays and time off are excluded.</div></div></div><div class="meeting-list">${(data.meetings||[]).map(mt=>`<div class="meeting-item ${mt.enabled?'':'muted-item'}"><div class="meeting-symbol">${icon('clock',18)}</div><div class="meeting-main"><strong>${esc(mt.title)}</strong><small>${esc(meetingRecurrenceLabel(mt))} · ${esc(mt.startTime)} · ${esc(mt.duration)} min</small><small>${esc(meetingPeopleLabel(mt))}${mt.requiresAttendeeReview?' · Needs attendee review':''}</small></div><div class="meeting-controls"><button class="mini-btn" data-action="toggle-meeting" data-id="${mt.id}" title="${mt.enabled?'Disable':'Enable'}">${mt.enabled?'Enabled':'Paused'}</button><button class="mini-btn" data-action="edit-meeting" data-id="${mt.id}">Edit</button><button class="icon-action" data-action="delete-meeting" data-id="${mt.id}" title="Delete meeting">${icon('trash',15)}</button></div></div>`).join('')||'<div class="grouped-note">No meetings yet. Add a regular event to reserve time automatically.</div>'}</div><div class="dialog-foot"><button class="btn" data-action="close-modal">Close</button><button class="btn primary" data-action="new-meeting">${icon('plus')} Add meeting</button></div>`;
 }else if(m.type==='meeting'){
 let mt=(data.meetings||[]).find(x=>x.id===m.id),edit=!!mt;
 const stored=mt?.recurrence||'workdays',recur=stored==='interval'?'weekly':stored;
 const weekday=Number(mt?.weekday??4),interval=stored==='interval'?Math.max(1,Number(mt?.interval)||1):1,nth=Number(mt?.nth??1);
 title=edit?'Edit recurring meeting':'New recurring meeting';subtitle='Choose a repeat pattern and attendees. Preview the upcoming dates before saving.';wide=true;
 content=`<form id="modalForm" data-form="meeting">${textField('Meeting name','title',mt?.title||'', 'required placeholder="e.g. Sprint planning"')}
 <div class="field-grid thirds"><div class="field"><label for="meetingStartTime">Start time</label><input id="meetingStartTime" name="startTime" type="time" value="${esc(mt?.startTime||'09:30')}" required></div>${numberField('Duration (minutes)','duration',mt?.duration||30,5,480,5)}${selectField('Repeat','recurrence',[['workdays','Every working day'],['weekly','Weekly'],['monthly','Monthly on a weekday']],recur)}</div>
 <div class="field-grid meeting-pattern" ${recur==='workdays'?'hidden':''}>${selectField('Day of week','weekday',[['1','Monday'],['2','Tuesday'],['3','Wednesday'],['4','Thursday'],['5','Friday'],['6','Saturday'],['0','Sunday']],String(weekday))}
 <div class="field" data-pattern-field="weekly" ${recur!=='weekly'?'hidden':''}><label for="meetingInterval">Repeat every (weeks)</label><input id="meetingInterval" type="number" name="interval" min="1" max="12" step="1" value="${interval}" required><small>1 means every week; 2 means every other week.</small></div>
 <div data-pattern-field="monthly" ${recur!=='monthly'?'hidden':''}>${selectField('Which occurrence','nth',[['1','1st of the month'],['2','2nd of the month'],['3','3rd of the month'],['4','4th of the month'],['5','5th of the month'],['-1','Last of the month']],String(nth))}</div></div>
 <div class="field-grid">${dateField('Active from','startDate',mt?.startDate||today())}<div class="field"><label for="meetingEndDate">Until (optional)</label><input id="meetingEndDate" type="date" name="endDate" value="${esc(mt?.endDate||'')}"></div></div>
 <div class="meeting-preview"><strong data-meeting-preview aria-live="polite"></strong><small data-meeting-dates></small></div>
 <fieldset class="meeting-attendees"><legend>Attendees</legend><label class="checkline meeting-audience"><input type="checkbox" name="allTeam" data-meeting-all ${mt?.allTeam!==false?'checked':''}><span><strong>Entire team</strong><small>Includes new team members automatically.</small></span></label>
 <p class="meeting-attendee-count" data-meeting-count aria-live="polite"></p>
 <div class="meeting-selection" ${mt?.allTeam!==false?'hidden':''}>${data.people.length>4?'<div class="field"><label for="meetingAttendeeSearch">Search attendees</label><input id="meetingAttendeeSearch" type="search" data-meeting-search placeholder="Name or workstream"></div>':''}
 <div class="meeting-people">${data.people.map(p=>`<label class="checkline meeting-person" data-attendee-name="${esc((p.name+' '+p.platform).toLowerCase())}"><input type="checkbox" name="person_${esc(p.id)}" data-meeting-person aria-label="${esc(p.name)}" ${mt?.attendees?.includes(p.id)?'checked':''}>${personAvatar(p.id)}<span class="meeting-person-name">${esc(p.name)}<small>${esc(p.platform)}</small></span></label>`).join('')||'<p class="panel-sub">Add team members to choose specific attendees.</p>'}</div></div>
 </fieldset>
 <div class="dialog-foot"><button type="button" class="btn" data-action="${view.setupStep===2?'setup-close-meeting':'manage-meetings'}">${view.setupStep===2?'Back to setup':'Back to meetings'}</button><button type="submit" class="btn primary" data-meeting-submit>${icon('check')} ${edit?'Save changes':'Create meeting'}</button></div></form>`;
 }else if(m.type==='iteration'){
 let i=iter();title='Iteration settings';subtitle='Define the reporting cadence and date range.';
 content=`<form id="modalForm" data-form="iteration"><div class="field"><label>Iteration</label><select name="iterationId">${data.iterations.map(it=>`<option value="${it.id}" ${it.id===i.id?'selected':''}>${esc(it.name)}</option>`).join('')}<option value="new">+ New iteration</option></select></div>${textField('Iteration name','name',i.name,'required')}<div class="field-grid">${dateField('Start','start',i.start)}${dateField('End','end',i.end)}</div><div class="dialog-foot">${submit('Save iteration')}</div></form>`;
 }else if(m.type==='help'){
 title='How Orbit works';subtitle='A quick tour of your resource-aware roadmap.';wide=true;
 content=`<div class="dialog-body" style="padding:0 0 5px"><div class="notice"><strong>One roadmap, two levels.</strong> Features are your strategic overview; expand any feature to see the actual stories and owners.</div><div class="grouped-note"><strong>1. Create a feature</strong><p>Give the epic a name and target date. Enter a user story, then select its teams, assignees and estimates. Each team becomes a separate work item. You can also add stories to an existing epic using its + button. Double-click the date axis to add a milestone.</p></div><div class="grouped-note"><strong>2. Let the plan calculate itself</strong><p>Orbit uses your dependency preferences, recurring meetings, weekends, holidays and planned absences. The feature bar is a direct roll-up of its child tasks.</p></div><div class="grouped-note"><strong>3. Stay in control</strong><p>Drag the row grip to reorder work or move it to another epic. Drag a task bar to shift its earliest start, or use the side inspector to edit effort, status, ownership and dependencies. Overlaps are warned about — never secretly reordered.</p></div><div class="grouped-note"><strong>4. Your private workspace</strong><p>Changes are saved to your account. Export a full workspace backup for portability. If saving fails, keep this tab open and retry or export your unsaved work.</p></div><div class="dialog-foot"><button class="btn primary" data-action="close-modal">Got it</button></div></div>`;
 }else if(m.type==='reset'){
 title='Reset this project?';subtitle='Clear this project’s features, team, meetings and milestones. Other projects remain untouched.';
 content=`<div class="notice warn" style="margin-bottom:15px">Only this project will be reset. Export JSON first if you want a backup.</div><div class="dialog-foot"><button class="btn" data-action="close-modal">Keep my changes</button><button class="btn danger" data-action="reset-confirm">Reset everything</button></div>`;
 }
 return `<div class="backdrop" data-action="modal-backdrop"><section class="dialog ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="dialog-head"><div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="icon-action" data-action="close-modal" title="Close">${icon('close',20)}</button></div><div class="dialog-body">${content}</div></section></div>`;
}
function footerTools(){return `<div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;padding:0 0 9px"><span class="bottom-tip">Changes are saved to your private workspace.</span><div style="flex:1"></div><button class="text-link" data-action="export">Export JSON</button><span style="color:#cfd4df">·</span><button class="text-link" data-action="import">Import JSON</button><input id="jsonImport" type="file" accept=".json,application/json" hidden><span style="color:#cfd4df">·</span><button class="text-link" data-action="reset">${'Reset project'}</button></div>`}
function setupWizard(){
 const step=view.setupStep,memberCount=data.people.length,meetingCount=data.meetings.length;
 const steps=[['1','Add your team','Names and roles'],['2','Recurring meetings','Protect focus time']];
 const stepper=steps.map(([n,label,detail],idx)=>`<div class="setup-step ${step===idx+1?'is-active':step>idx+1?'is-past':''}"><span class="setup-step-num">${step>idx+1?icon('check',14):n}</span><span><strong>${label}</strong><small>${detail}</small></span></div>`).join('');
 let main,aside,foot;
 if(step===1){
  main=`<h2>Add your team</h2><p class="setup-sub">Start with people's names and job roles. If a role doesn't exist, Orbit creates it automatically.</p>
   <form class="setup-form" id="onboardingMemberForm"><div class="field-grid thirds">
   <div class="field"><label for="onboardFirst">First name</label><input id="onboardFirst" name="firstName" required placeholder="e.g. Ihor" autofocus maxlength="90"></div>
   <div class="field"><label for="onboardLast">Last name</label><input id="onboardLast" name="lastName" required placeholder="e.g. Shevchenko" maxlength="90"></div>
   <div class="field"><label for="onboardRole">Role</label><input id="onboardRole" name="role" required placeholder="e.g. Backend Developer" list="onboardingRoles" maxlength="120" autocomplete="off"><datalist id="onboardingRoles">${data.roles.map(r=>`<option value="${esc(r.name)}"></option>`).join('')}</datalist></div></div>
   <div class="setup-role-preview" id="setupRolePreview">A new role will automatically create its workstream.</div><button type="submit" class="btn primary">${icon('plus',15)} Add team member</button></form>
   ${sourceProjectOptions()?`<div class="setup-import-strip"><div><strong>${icon('copy',14)} Or copy an existing team</strong><small>Imports people and roles. Existing members will not be duplicated.</small></div><div class="setup-import-controls"><select id="teamImportSource" aria-label="Source project for team">${sourceProjectOptions()}</select><button class="btn sm" data-action="setup-import-team">${icon('copy',13)} Copy team</button></div></div>`:''}
   <div class="setup-added-title">Team members added <span class="soft-tag">${memberCount}</span></div>
   ${memberCount?data.people.map(p=>`<div class="setup-member">${personAvatar(p.id,'avatar')}<div><strong>${esc(p.name)}</strong><small>${esc(p.role)} · ${esc(p.platform)}</small></div><button class="icon-action" data-action="setup-remove-member" data-id="${p.id}" title="Remove from this project">${icon('trash',15)}</button></div>`).join(''):'<div class="setup-empty">No team members yet. Add someone above, or skip this step.</div>'}`;
  aside=`<h3>${icon('bolt',15)} Roles become workstreams</h3><p>No need to set up a role directory first. Type a role and Orbit will create it, then use its workstream in the Platform selector when you add work items.</p><div class="aside-example"><b>Backend Developer</b> → Backend<br><b>QA Engineer</b> → QA<br><b>iOS Developer</b> → iOS</div><p style="margin-top:15px;margin-bottom:0">You can rename roles or adjust their workstreams later under Team settings.</p>`;
  foot=`<span>${memberCount?`${memberCount} member${memberCount===1?'':'s'} added`:'You can configure your team later.'}</span><div style="display:flex;gap:9px"><button class="btn ghost" data-action="setup-next">Skip for now</button><button class="btn primary" data-action="setup-next">Continue to meetings ${icon('chevron',14)}</button></div>`;
 }else{
  main=`<div class="split-head"><div><h2>Add recurring meetings</h2><p class="setup-sub">Meetings reduce each attendee's available development capacity and automatically update task forecasts.</p></div><button class="btn primary" data-action="setup-add-meeting">${icon('plus',15)} Add meeting</button></div>
   ${sourceProjectOptions()?`<div class="setup-import-strip"><div><strong>${icon('copy',14)} Or copy meeting schedules</strong><small>Copies recurrence, timing and attendees. Unmatched participants require review.</small></div><div class="setup-import-controls"><select id="meetingImportSource" aria-label="Source project for meetings">${sourceProjectOptions()}</select><button class="btn sm" data-action="setup-import-meetings">${icon('copy',13)} Copy meetings</button></div></div>`:''}
   <div class="setup-meeting-list">${meetingCount?data.meetings.map(mt=>`<div class="meeting-item"><div class="meeting-symbol">${icon('clock',18)}</div><div class="meeting-main"><strong>${esc(mt.title)}</strong><small>${esc(meetingRecurrenceLabel(mt))} · ${esc(mt.startTime)} · ${mt.duration} min</small><small>${esc(meetingPeopleLabel(mt))}${mt.requiresAttendeeReview?' · Needs attendee review':''}</small></div><button class="mini-btn" data-action="setup-edit-meeting" data-id="${mt.id}">Edit</button><button class="icon-action" data-action="delete-meeting" data-id="${mt.id}" title="Delete meeting">${icon('trash',15)}</button></div>`).join(''):'<div class="setup-empty">No meetings configured. Add a daily, weekly, biweekly or monthly meeting — or skip for now.</div>'}</div>
   <div class="grouped-note" style="margin-top:18px"><strong>Capacity calculation</strong><p>The timeline reserves work and meetings in 0.5-day steps. Actual meeting durations stay unchanged. All available work time goes toward the estimate. Recurring meetings are deducted once; weekends, holidays and absences extend the calendar duration.</p></div>`;
  aside=`<h3>${icon('clock',15)} Plan with real availability</h3><p>Configure daily standups, weekly syncs, every second Thursday, or the third Thursday of each month. Choose duration and attendees.</p><div class="aside-example"><b>Daily sync</b> · Every workday · 15 min<br><b>Planning</b> · Every 2 weeks · 60 min<br><b>Demo</b> · 3rd Thursday · 45 min</div><p style="margin-top:15px;margin-bottom:0">Edit these later in Settings → Recurring meetings.</p>`;
  foot=`<button class="btn" data-action="setup-back">${icon('chevronleft',14)} Back to team</button><div style="display:flex;gap:9px"><button class="btn ghost" data-action="setup-finish">Skip for now</button><button class="btn primary" data-action="setup-finish">${icon('check',15)} Finish setup</button></div>`;
 }
 return `<div class="setup-shell"><div class="setup-top"><div class="setup-brand"><span class="brand-mark">${icon('target',19)}</span>orbit<small>PLANNER</small></div><button class="btn sm ghost" data-action="setup-finish">Finish setup & open roadmap ${icon('chevron',14)}</button></div>
 <main class="setup-main"><div class="setup-kicker">NEW PROJECT · ${esc(currentProject().name)}</div><h1>Make your roadmap work for your team.</h1><p class="setup-desc">Two quick setup steps. Add your people and reserve their recurring meeting time so Orbit can forecast realistic delivery dates. You can skip either one.</p>
 <div class="setup-progress" aria-label="Setup progress">${stepper}</div><div class="setup-layout"><section class="setup-card">${main}</section><aside class="setup-aside">${aside}</aside></div><div class="setup-footer">${foot}</div></main></div>`;
}

function welcomeMarkup(){return `<div class="empty-workspace"><header class="empty-top"><span class="entry-logo"><span class="brand-mark">${icon('target',20)}</span>orbit</span><button class="btn" data-action="logout">Log out</button></header><main class="empty-content"><div class="empty-icon">${icon('layers',38)}</div><h1>Let's create your first project.</h1><p>Give your project a name, add your team and their roles, then reserve recurring meeting time. Both setup steps are optional.</p><button class="btn primary" data-action="new-project">${icon('plus',16)} Create project</button></main></div>`;}
function syncMeetingForm(){
 const form=$('#modalForm[data-form="meeting"]');if(!form)return;
 const field=name=>form.querySelector(`[name="${name}"]`);
 const recur=field('recurrence').value,interval=Number(field('interval').value||1);
 $('.meeting-pattern').hidden=recur==='workdays';
 $$('[data-pattern-field]').forEach(group=>{
  group.hidden=group.dataset.patternField!==recur;
  group.querySelectorAll('input,select').forEach(input=>input.disabled=group.hidden);
 });
 const allTeam=field('allTeam').checked,selected=form.querySelectorAll('[data-meeting-person]:checked').length;
 $('.meeting-selection').hidden=allTeam;
 const count=$('[data-meeting-count]');
 count.textContent=allTeam?`Entire team · ${data.people.length} member(s)`:`${selected} of ${data.people.length} attendees selected`;
 count.classList.toggle('empty',!allTeam&&!selected);
 $('[data-meeting-submit]').disabled=!allTeam&&!selected;
 const search=($('[data-meeting-search]')?.value||'').trim().toLowerCase();
 $$('[data-attendee-name]').forEach(label=>label.hidden=!label.dataset.attendeeName.includes(search));
 const preview=$('[data-meeting-preview]'),dates=$('[data-meeting-dates]');dates.textContent='';
 if(recur==='weekly'&&(!Number.isInteger(interval)||interval<1||interval>12)){preview.textContent='Choose a repeat interval of 1–12 whole weeks.';return;}
 const draft={enabled:true,recurrence:recur==='weekly'&&interval>1?'interval':recur,interval,
  weekday:Number(field('weekday').value),nth:Number(field('nth').value),startDate:field('startDate').value,endDate:field('endDate').value};
 preview.textContent=meetingRecurrenceLabel(draft);
 const start=asDay(draft.startDate);if(!Number.isFinite(start))return;
 const first=Math.max(start,asDay(today())),upcoming=[];
 for(let offset=0;offset<370&&upcoming.length<3;offset++){
  const date=fromDay(first+offset);if(draft.endDate&&date>draft.endDate)break;
  if(meetingOccurs(draft,date))upcoming.push(fullD(date));
 }
 dates.textContent=upcoming.length?`Next: ${upcoming.join(' · ')}`:'No upcoming dates in the selected range.';
}
function accessibility(){
 $$('label').forEach((label,index)=>{
  if(label.querySelector('input,select,textarea'))return;
  if(label.htmlFor&&root.querySelector('#'+CSS.escape(label.htmlFor)))return;
  const field=label.parentElement?.querySelector('input,select,textarea');
  if(field){field.id||='orbit-field-'+index;label.htmlFor=field.id;}
 });
 $$('[role="dialog"],.drawer').forEach(dialog=>{dialog.setAttribute('tabindex','-1');});
}
listen(document,'keydown',event=>{
 const dialog=$('[role="dialog"]')||$('.drawer');
 if(!dialog||event.key!=='Tab')return;
 const fields=[...dialog.querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled&&el.getClientRects().length);
 const first=fields[0],last=fields.at(-1);
 if(event.shiftKey&&(document.activeElement===first||!dialog.contains(document.activeElement))){event.preventDefault();last?.focus();}
 else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}
});

function render(){cancelAnimationFrame(panFrame);if(!workspace.projects.length){$('#orbit-canvas').innerHTML=sanitizeMarkup(welcomeMarkup()+modalMarkup());accessibility();return;}computed=calcSchedule();timeBreakdowns.clear();let scroll=$('#ganttScroller'),left=scroll?.scrollLeft||0,top=scroll?.scrollTop||0;
 if(!scroll&&view.page==='timeline')view.scrollToStart=true;
 if(view.scrollToStart)Object.assign(view,timelineWindow(view.scaleFocusDate||today(),SCALES[view.scale].days,view.zoom,Math.max(1,root.clientWidth-200)));
 let content=view.page==='timeline'?timelineView():view.page==='availability'?availabilityView():view.page==='team'?teamView():milestoneView();
 const markup=view.setupStep?`${setupWizard()}${modalMarkup()}`:`<div class="app ${view.sidebarHidden?'nav-hidden':''} ${view.page==='timeline'?'timeline-page':''}">${sideNav()}<main class="main">${mainHeader()}<div class="content">${view.page==='timeline'?'':heading()}${content}${view.page==='timeline'?'':footerTools()}</div></main></div>${drawerMarkup()}${modalMarkup()}`;
 $('#orbit-canvas').innerHTML=sanitizeMarkup(markup);
 let newer=$('#ganttScroller');if(newer){
  newer.scrollLeft=(view.scrollToStart?focusOffset(view.scaleFocusDate||today(),view.rangeStart,view.zoom,trackWidth(newer)):left);newer.scrollTop=top;
  let lastLeft=newer.scrollLeft;newer.onscroll=()=>{syncLinkTargets();if(Math.abs(newer.scrollLeft-lastLeft)<.01)return;lastLeft=newer.scrollLeft;queueTimelinePan(newer);};
  newer.onwheel=e=>{if(Math.abs(e.deltaX)>Math.abs(e.deltaY)&&((e.deltaX<0&&newer.scrollLeft<2)||(e.deltaX>0&&newer.scrollLeft>=newer.scrollWidth-newer.clientWidth-2)))queueTimelinePan(newer);};
 }view.scrollToStart=false;accessibility();syncMeetingForm();syncStoryTeams();syncDependencySettings();drawDependencyLines();
}
